		counter packets 195894 bytes 317650084 jump KUBE-FIREWALL
	}

	chain KUBE-KUBELET-CANARY {
	}
}
table ip6 nat {
	chain KUBE-KUBELET-CANARY {
	}
}
table ip6 filter {
